  (op + 384 <= fl \/ fl + 1 <= op) -> (((op / 8) + 2147450880) + 48 <= ((F / 8) + 2147450880) \/ ((F / 8) + 2147450880) + 32 <= ((op / 8) + 2147450880)) ->
  L5.u64_at RSEGS M (E - 8) (bv_unsigned (getr R0 (reg 1))) -> L5.u64_at RSEGS M (E - 16) (bv_unsigned (getr R0 (reg 8))) ->
